import{_ as o,l as r,o as a,c as n,v as t,p as s,x as l,d as p,i as E,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"Hellwig 竞争性 REE","description":"","frontmatter":{"title":"Hellwig 竞争性 REE","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/hellwig-ree.md","filePath":"econ/hellwig-ree.md","lastUpdated":1789023840000}'),h={name:"econ/hellwig-ree.md"};function _(c,e,m,A,g,B){const i=r("Mermaid");return a(),n("div",null,[e[1]||(e[1]=t('<h1 id="hellwig-竞争性-ree" tabindex="-1">Hellwig 竞争性 REE <a class="header-anchor" href="#hellwig-竞争性-ree" aria-label="Permalink to &quot;Hellwig 竞争性 REE&quot;">​</a></h1><div class="epigraph"><p>连续统里每个人把价格当参数；价格仍由全体信号与噪声共同决定，因而可以部分揭示而不给单个人操纵的余地。</p><footer>—— Hellwig, On the Aggregation of Information in Competitive Markets, Journal of Economic Theory, 1980</footer></div><p><a href="/econ/grossman-stiglitz">上一课</a>用随机供给保住了部分揭示，但「价格接受」在有限知情者那里只是近似：大户理论上能影响 \\(p\\)。本课缺口是把 REE 放到连续统上，让竞争性假设名副其实。不重写 \\(c\\) 与 \\(\\lambda\\) 的无差异，不把噪声改成订单簿。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>理性预期均衡要求：需求是在以价格为条件的信念下最优的，而价格又是这些需求加总后的出清值。有限人时，个人理应把「我多买一点 \\(p\\) 会动」写进一阶条件，于是对象变成战略博弈，不再是竞争。Hellwig（1980）取连续统投资者，每人持有自己的信号 \\(s_i=\\theta+\\varepsilon_i\\)，加总供给仍带噪声。单个人的 \\(s_i\\) 对 \\(p\\) 的影响为零，价格接受是精确的，不是借口。</p><p>缺口是：<strong>竞争性</strong>部分揭示如何把分散信号聚合成一个公共统计量。GS 强调采集激励；本课强调加总。后课 Admati 再把一种资产换成多种。</p><p><span class="marginnote">Hellwig, <em>JET</em> 22, 1980。连续统加独立特质噪声，大数定律把 \\(\\varepsilon_i\\) 洗掉，留下 \\(\\theta\\) 与总供给。价格是这两个总量的函数，不是任何人的私器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>CARA、正态、线性猜测：设 \\(p=a+b\\theta+d z\\)，每人用 \\((s_i,p)\\) 做贝叶斯更新，需求对 \\(p\\) 线性。出清后核对系数，得到唯一的线性 REE。\\(b/d\\) 的比决定揭示深度：信号越准、风险容忍越高、噪声供给越稳，价格越靠近 \\(\\theta\\)。个人仍从 \\(p\\) 学到别人的信号平均，但学不完——\\(z\\) 与 \\(\\theta\\) 绑在同一个观测里。</p><p>与 GS 的分工：那里 \\(\\lambda\\) 是内生选择「买不买同一信号」；这里每人已经有一份特异信号，问题是市场怎样把它们加总。两篇可以叠：先按 Hellwig 加总，再让「是否获得 \\(s_i\\)」付成本。本课只钉竞争性加总。</p>',10)),(a(),s(d,null,{default:l(()=>[E(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22%E6%AF%8F%E4%BA%BA%20s_i%22%5D%20--%3E%20DEM%5B%22%E4%BB%B7%E6%A0%BC%E6%8E%A5%E5%8F%97%E7%9A%84%E9%9C%80%E6%B1%82%22%5D%0A%20%20DEM%20--%3E%20CLR%5B%22%E5%87%BA%E6%B8%85%3A%20p%20%3D%20a%20%2B%20b%20%CE%B8%20%2B%20d%20z%22%5D%0A%20%20CLR%20--%3E%20UPD%5B%22%E7%94%A8%20p%20%E6%9B%B4%E6%96%B0%20%CE%B8%22%5D%0A%20%20UPD%20--%3E%20PART%5B%22%E9%83%A8%E5%88%86%E6%8F%AD%E7%A4%BA%E7%9A%84%E7%AB%9E%E4%BA%89%E6%80%A7%20REE%22%5D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>不要把线性 REE 写成做市商定价规则。这里没有指定的中间人，只有瓦尔拉斯出清。指定中间人、战略下单，是后课把 Kyle 放进均衡框架时才对照的对象；协议本身见 <a href="/econ/to-limit-order-book">到限价簿</a> 之后的量化栏。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是大数与混淆。特质噪声在加总里消失，所以 \\(p\\) 确实携带 \\(\\theta\\)；总量噪声不消失，所以 \\(p\\) 不是 \\(\\theta\\) 的充分统计。竞争保证没有人能靠「假装需求」去扭曲这个统计量——扭曲的收益阶数小于连续统。于是「从价格学习」与「把价格当给定」不再打架：学习的是别人已经决定的加总，不是自己的影子。</p><p>若把连续统改回有限 \\(N\\)，每人应内部化信息泄漏与价格冲击，线性猜测一般不是均衡。那是战略 REE / Kyle 的地盘。本课把刀刃留在 \\(N=\\infty\\)。</p><p><span class="marginnote">Radner 的「理性预期」原是现货市场对未来现货价格的预期一致。金融里的 REE 多了一步：现货价格本身是别人私人信息的统计。Hellwig 把这一步写成竞争。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>线性正态是为了闭式，不是一般定义。非正态时竞争性 REE 仍可谈存在与揭示，下一课之后会碰到存在性本身就不平凡。也不要把「连续统」读成「没有人拥有信息」：每人有 \\(s_i\\)，只是没有市场力。</p><p>本课不估计 \\(b\\)、\\(d\\)，不把高频价格冲击当成 \\(z\\)。\\(z\\) 是理论噪声，量化栏的冲击有时间戳与队列。后课默认：竞争性 REE 是价格接受下的部分揭示加总；个人对 \\(p\\) 无影响，仍从 \\(p\\) 学习总量。</p><p>下一课把一种风险资产换成多种：价格向量带来<strong>跨资产</strong>学习，也带来混淆哪一个 \\(\\theta\\) 在动。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>连续统使价格接受与从价格学习相容。</li><li>线性竞争性 REE 把分散信号加总进 \\(p\\)，总量噪声阻止完全揭示。</li><li>本课不写战略下单，也不写限价簿。</li><li>出处：Hellwig, <em>JET</em> 1980。</li></ul>',11))])}const R=o(h,[["render",_]]);export{u as __pageData,R as default};
